package com.unbeat.playlist.userplaylist.dto

import com.fasterxml.jackson.annotation.JsonProperty

data class PlaylistRequest(
    val name: String
)

// Kotlin의 "is"로 시작하는 Boolean 프로퍼티(isAutoGenerated, isPublic)는 JVM 게터가
// isAutoGenerated()/isPublic()로 생성되는데, Jackson이 자바빈 관례("is" 접두사는 프로퍼티
// 이름에서 제외)를 그대로 적용해서 실제 JSON은 autoGenerated/public으로 나가버리는 이슈가
// 있음(라이브 테스트 중 발견, 2026-10-10 — 프론트가 기대하는 isPublic과 실제 응답이 달라서
// 공개/비공개 표시가 항상 틀리게 보였을 것). @get:JsonProperty로 직렬화 이름을 명시적으로 고정.
data class PlaylistResponse(
    val id: Long,
    val name: String,
    val createdAt: String,
    val trackCount: Int,
    @get:JsonProperty("isAutoGenerated") val isAutoGenerated: Boolean,
    @get:JsonProperty("isPublic") val isPublic: Boolean
)

// (게이미피케이션 2단계) 공개 전환 요청 — 로그인(Authorization 헤더)이 있어야만 true로 바꿀 수 있음.
//
// 400 "no delegate- or property-based Creator" 에러의 실제 원인(2026-10-10, 서버 로그로 확인):
// 필드가 isPublic 하나뿐인 데이터 클래스라서, Jackson이 이 프로퍼티를 "생성자 파라미터 이름
// isPublic"과 "게터 isPublic()을 자바빈 관례로 깐 이름 public" 두 개의 서로 다른 이름으로 인식함.
// 프로퍼티가 여러 개면 그냥 이름이 어긋난 채로 섞여 쓰이는 정도(위 PlaylistResponse에서 실제로
// 벌어진 문제)에서 끝나지만, 프로퍼티가 단 하나뿐인 생성자는 Jackson이 "properties-creator"로
// 쓸지 "delegate-creator"(JSON 원시값 하나를 통째로 받는 생성자)로 쓸지를 프로퍼티 이름 일치
// 여부로 판단하는데, 위 이름 충돌 때문에 양쪽 다 실패로 판정돼서 "Creator는 있는데 둘 다
// 아니다"라는 이 에러가 남. @get(게터)과 @param(생성자 파라미터) 양쪽을 모두 "isPublic"으로
// 명시적으로 고정해서 충돌 자체를 없앰 — 위 PlaylistResponse처럼 @get만 있으면 생성자 쪽
// 이름 충돌이 그대로 남아 이 버그가 재현됨(요청 바디를 받는 DTO라서 생성자 쪽도 반드시 필요).
// category(랭킹 카테고리 필터, 2026-10-10 추가) — isPublic=true로 바꿀 때만 필수(서비스
// 레이어에서 검증, MUSIC_CATEGORIES 참고). isPublic=false(비공개 전환)일 땐 안 써도 됨이라
// nullable + 기본값 null. 필드가 둘이 되면서 위에서 설명한 단일 Boolean 파라미터 creator
// 버그 대상에서는 벗어나지만, isPublic 쪽 @get/@param 고정은 안전하게 그대로 둠.
data class PlaylistVisibilityRequest(
    @get:JsonProperty("isPublic")
    @param:JsonProperty("isPublic")
    val isPublic: Boolean,
    val category: String? = null
)

// 공개 피드용. 처음엔 닉네임 체계가 없어서 소유자 식별 정보를 아예 안 보여줬는데(차트처럼 재생목록
// 자체만 노출), "닉네임을 눌러서 그 사람 페이지로 들어가는 게 낫겠다"는 피드백으로 ownerNickname을
// 추가함(2026-10-10). 공개 전환이 이제 닉네임 설정을 강제하긴 하지만, 그 전에 이미 공개로 전환된
// 레코드(닉네임 도입 이전 데이터)는 소유자가 아직 닉네임이 없을 수 있어 nullable로 둠 — 프론트가
// null이면 "익명"으로 표시. 좋아요 수는 3단계(좋아요 테이블)가 생기면 여기 추가될 예정.
// coverImageUrl(랭킹 피드 매거진형 카드 디자인, 2026-10-10 추가) — 담긴 곡 중 이미지가 있는
// 가장 최근 곡 하나를 대표 커버로 사용. 곡이 아예 없거나 전부 이미지가 없으면 null(프론트가
// 단색 플레이스홀더로 대체).
// likeCount/likedByMe(게이미피케이션 3단계, 같은 날 추가) — 등수 배지(금/은/동)는 "짜치다"는
// 반응으로 빼고, 좋아요 숫자만 남기기로 함. 피드 정렬 자체가 이 likeCount 내림차순이라 숫자
// 배지 없이도 카드가 나열된 순서가 곧 랭킹(PlaylistService.listPublic 참고). likedByMe는
// 요청자가 로그인 안 했으면 항상 false(좋아요 여부를 알려면 누구인지 알아야 하므로).
// category(랭킹 카테고리 필터, 2026-10-10 추가) — MUSIC_CATEGORIES의 키 값(예: "kpop"). 닉네임
// 도입 이전처럼 카테고리 도입 이전에 이미 공개됐던 레코드는 null일 수 있어 nullable — 프론트
// 필터 칩에서 "전체"를 고르면 null인 것도 그대로 보이고, 특정 카테고리를 고르면 안 보임.
data class PublicPlaylistResponse(
    val id: Long,
    val name: String,
    val createdAt: String,
    val trackCount: Int,
    val ownerNickname: String?,
    val coverImageUrl: String?,
    val likeCount: Int,
    val likedByMe: Boolean,
    val category: String?
)

data class PlaylistTrackRequest(
    val artistName: String,
    val trackName: String,
    val trackUrl: String? = null,
    val imageUrl: String? = null
)

data class PlaylistTrackResponse(
    val id: Long,
    val artistName: String,
    val trackName: String,
    val url: String?,
    val imageUrl: String?,
    val addedAt: String
)
